//! The desktop writes JSON and JUnit reports from `runnerReport.js`; the core
//! port must produce the same bytes so CI readers see one format. The
//! fixtures under `tests/fixtures/report` were generated by the JavaScript
//! side and are asserted there as well.
use resonance_core::report::{summarize, to_json, to_junit};
use resonance_core::results::RunResult;

fn run() -> RunResult {
    serde_json::from_str(include_str!("../../../tests/fixtures/report/run.json")).unwrap()
}

#[test]
fn summary_matches_the_shared_fixture_byte_for_byte() {
    let expected = include_str!("../../../tests/fixtures/report/summary.json");
    assert_eq!(to_json(&summarize(&run())), expected);
}

#[test]
fn junit_matches_the_shared_fixture_byte_for_byte() {
    let expected = include_str!("../../../tests/fixtures/report/junit.xml");
    assert_eq!(to_junit(&summarize(&run())), expected);
}

#[test]
fn summary_is_idempotent_through_json() {
    let summary = summarize(&run());
    let reparsed: resonance_core::report::RunSummary =
        serde_json::from_str(&to_json(&summary)).unwrap();
    assert_eq!(to_json(&reparsed), to_json(&summary));
}
